import json
import re
import datetime
import hashlib
from zoneinfo import ZoneInfo

# Knowledge layout
PR_SETTINGS = "Payroll/settings.json"
PR_CLIENTS = "Payroll/clients.json"
PR_LEDGER = "Payroll/Mail/outlook.json"
MAIL_SERVER = "m365-mail-read"
MAIL_FIRST_RUN_HOURS = 24
# Emails handled per run (oldest first); the rest wait for the next run, which starts where this one stopped.
MAIL_PER_RUN = 20
MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]


def pr_read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def pr_tz(settings):
    for name in (str((settings or {}).get("timezone") or ""), "Australia/Sydney"):
        try:
            if name:
                return ZoneInfo(name)
        except Exception:
            continue
    return datetime.timezone(datetime.timedelta(hours=10))


def pr_slug(name):
    return re.sub(r"[^a-z0-9]+", "-", str(name or "").lower()).strip("-")


def pr_clients(raw):
    """Payroll/clients.json as [{slug, name, other_names, senders, assignee_email}]. Senders are full addresses or
    @domain entries, lower-cased."""
    rows = raw.get("clients") if isinstance(raw, dict) else raw
    out = []
    for c in rows or []:
        if not isinstance(c, dict) or not str(c.get("name") or "").strip():
            continue
        name = str(c["name"]).strip()
        senders = [str(s or "").strip().lower() for s in c.get("senders") or [] if str(s or "").strip()]
        out.append({"slug": str(c.get("slug") or pr_slug(name)), "name": name,
                    "other_names": [str(n) for n in c.get("other_names") or [] if str(n or "").strip()],
                    "senders": senders, "assignee_email": str(c.get("assignee_email") or "").strip().lower()})
    return out


def pr_sender(value):
    """The address in "Name <address>" (or a bare address), lower-cased."""
    m = re.search(r"[\w.+'-]+@[\w-]+(\.[\w-]+)+", str(value or ""))
    return m.group(0).lower() if m else ""


def pr_client_for_sender(clients, sender):
    """The one client whose senders list this address or its domain; None when none or more than one do."""
    if not sender:
        return None
    domain = "@" + sender.split("@", 1)[1]
    hits = [c for c in clients if sender in c["senders"]]
    if not hits:
        hits = [c for c in clients if domain in c["senders"]]
    return hits[0] if len(hits) == 1 else None


def pr_when(value):
    s = str(value or "").strip()
    if not s:
        return None
    try:
        d = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
    except ValueError:
        return None
    return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)


def pr_iso(when):
    return when.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def pr_day(d):
    """05-Sep-26"""
    return "%02d-%s-%02d" % (d.day, MONTHS[d.month - 1], d.year % 100)


def pr_preview(text):
    """The email's opening text, safe to keep in run history: mail-system banners ("Caution: This email is from an
    external sender…") taken off the top, then scrubbed like WorkQ text."""
    s = str(text or "").replace("\r\n", "\n").strip()
    for _ in range(3):
        first, _sep, rest = s.partition("\n\n")
        if len(first) < 400 and re.search(r"(?i)(external sender|outside (of )?(your|the) organi[sz]ation|"
                                          r"^\s*\[?(caution|external|warning)\b)", first):
            s = rest.strip()
        else:
            break
    return pr_scrub(s)


def pr_auth_error(text):
    """True when a connector error means the sign-in has expired or been revoked."""
    return bool(re.search(r"(?i)invalid_token|expired|unauthori[sz]ed|\b401\b|reconnect|not connected|invalid_grant",
                          str(text or "")))


def pr_scrub(text):
    """Belt and braces on anything written to WorkQ: TFNs, BSBs, account and card numbers, and dollar amounts never
    leave the mailbox, whatever the AI returned."""
    s = str(text or "")
    s = re.sub(r"(?i)\b(tfn|tax file number)\b[^\n]{0,40}", "[removed]", s)
    s = re.sub(r"(?i)\b(bsb|account (no|number)|acc no)\b[^\n]{0,40}", "[removed]", s)
    s = re.sub(r"\b\d{3}[- ]?\d{3}[- ]?\d{3,}\b", "[number removed]", s)
    s = re.sub(r"\b\d{6,}\b", "[number removed]", s)
    s = re.sub(r"(A?\$|AUD)\s?\d[\d,]*(\.\d+)?", "[amount]", s)
    return s.strip()

# ── cut-off timers: shared helpers ──
PR_TIMERS = "Payroll/Mail/timers.json"
SEND_SERVER = "m365-mail-send"
DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
# Occurrences still worked on after their day (e.g. a 6 pm due time followed up next morning).
TIMER_LOOKBACK_DAYS = 3


def tm_time(value):
    m = re.match(r"^\s*(\d{1,2}):(\d{2})\s*$", str(value or ""))
    if not m or int(m.group(1)) > 23 or int(m.group(2)) > 59:
        return None
    return datetime.time(int(m.group(1)), int(m.group(2)))


def tm_weekday(value):
    s = str(value or "").strip()[:3].title()
    return DAYS.index(s) if s in DAYS else None


def tm_minutes(value, default):
    if value is None or value == "":
        return default
    try:
        n = int(value)
    except (TypeError, ValueError):
        return "bad"
    return n if n >= 0 else "bad"


def tm_timers(raw, settings):
    """Each client's "timers" in Payroll/clients.json, checked. Returns (timers, problems): a timer with anything
    unclear is left out and named in problems, never guessed."""
    rows = raw.get("clients") if isinstance(raw, dict) else raw
    timers, problems = [], []
    for c in rows or []:
        if not isinstance(c, dict) or not str(c.get("name") or "").strip():
            continue
        name = str(c["name"]).strip()
        slug = str(c.get("slug") or pr_slug(name))
        tz_name = str(c.get("timezone") or (settings or {}).get("timezone") or "Australia/Sydney")
        try:
            ZoneInfo(tz_name)
        except Exception:
            problems.append(name + ": unknown timezone \"" + tz_name + "\"")
            continue
        for i, t in enumerate(c.get("timers") or []):
            if not isinstance(t, dict):
                continue
            label = str(t.get("name") or "").strip() or ("timer " + str(i + 1))
            where = name + ", " + label + ": "
            bad = []
            every = str(t.get("every") or "week").strip().lower()
            if every not in ("week", "fortnight", "month"):
                bad.append("\"every\" must be week, fortnight or month")
            day = None
            weekday = None
            if every == "month":
                d = str(t.get("day") or "").strip().lower()
                if d == "last":
                    day = "last"
                elif d.isdigit() and 1 <= int(d) <= 28:
                    day = int(d)
                else:
                    bad.append("\"day\" must be 1 to 28, or \"last\"")
            else:
                weekday = tm_weekday(t.get("day"))
                day = weekday
                if weekday is None:
                    bad.append("\"day\" must be Mon to Fri")
                elif weekday >= 5:
                    bad.append("\"day\" must be a weekday (timers only run Monday to Friday)")
            first = None
            if every == "fortnight":
                try:
                    first = datetime.date.fromisoformat(str(t.get("first_date") or ""))
                    if weekday is not None and first.weekday() != weekday:
                        bad.append("\"first_date\" isn't a " + DAYS[weekday])
                except ValueError:
                    bad.append("\"first_date\" (one date it falls on, YYYY-MM-DD) is needed for a fortnightly timer")
            due = tm_time(t.get("due"))
            if not due:
                bad.append("\"due\" must be a time like 10:30")
            remind = tm_time(t.get("remind_at")) if t.get("remind_at") else None
            if t.get("remind_at") and not remind:
                bad.append("\"remind_at\" must be a time like 09:00")
            elif remind and due and remind >= due:
                bad.append("\"remind_at\" must be before \"due\"")
            cutoff = tm_time(t.get("cutoff")) if t.get("cutoff") else None
            if t.get("cutoff") and not cutoff:
                bad.append("\"cutoff\" must be a time like 11:00")
            elif cutoff and due and cutoff < due:
                bad.append("\"cutoff\" can't be before \"due\"")
            follow = tm_minutes(t.get("follow_up_after"), 30)
            escalate = tm_minutes(t.get("escalate_after"), 60)
            if follow == "bad" or escalate == "bad":
                bad.append("\"follow_up_after\" and \"escalate_after\" are minutes after the due time")
            elif escalate and escalate <= follow:
                bad.append("\"escalate_after\" must be later than \"follow_up_after\"")
            done_when = str(t.get("done_when") or "email").strip().lower()
            if done_when not in ("email", "workq"):
                bad.append("\"done_when\" must be email or workq")
            kinds = [str(k).strip().lower() for k in (t.get("kinds") or ["timesheets"]) if str(k or "").strip()]
            contacts = [str(a or "").strip().lower() for a in t.get("contacts") or [] if str(a or "").strip()]
            wrong = [a for a in contacts if not re.match(r"^[\w.+'-]+@[\w-]+(\.[\w-]+)+$", a)]
            if wrong:
                bad.append("not an email address: " + ", ".join(wrong))
            if bad:
                problems.append(where + "; ".join(bad))
                continue
            timers.append({
                "key": slug + "|" + pr_slug(label), "client": name, "client_slug": slug, "name": label,
                "every": every, "day": day, "first": first, "due": due, "remind": remind, "cutoff": cutoff,
                "follow": follow, "escalate": escalate or None, "done_when": done_when, "kinds": kinds,
                "contacts": contacts, "tz": tz_name,
                "assignee_email": str(c.get("assignee_email") or "").strip().lower(),
            })
    return timers, problems


def tm_falls_on(t, d):
    """True when timer t is due on local date d."""
    if t["every"] == "month":
        if t["day"] == "last":
            return (d + datetime.timedelta(days=1)).month != d.month
        return d.day == t["day"]
    if d.weekday() != t["day"]:
        return False
    return t["every"] == "week" or (d - t["first"]).days % 14 == 0


def tm_period_days(t):
    return {"week": 7, "fortnight": 14, "month": 28}[t["every"]]


def tm_at(d, tm, tz):
    return datetime.datetime.combine(d, tm).replace(tzinfo=tz)


def tm_clock(when, tz):
    """"10:30 Mon 02-Nov-26" in the client's time zone."""
    local = when.astimezone(tz)
    return local.strftime("%H:%M") + " " + DAYS[local.weekday()] + " " + pr_day(local)


def tm_hm(when, tz):
    return when.astimezone(tz).strftime("%H:%M")

# ── Check the timers ──
# Works out which reminders, follow-ups, escalations and cut-offs are due now. Changes nothing.
settings = pr_read_json(PR_SETTINGS) or {}
timers, problems = tm_timers(pr_read_json(PR_CLIENTS), settings)
intake = pr_read_json(PR_LEDGER) or {}
state = pr_read_json(PR_TIMERS) or {}
occurrences = state.get("occurrences") or {}
now = datetime.datetime.now(datetime.timezone.utc)
actions = []
status = []


def _received(t, start, end):
    """When the client's payroll email of the right kind first arrived in [start, end], from the email intake's
    record. None when it hasn't."""
    hits = []
    for v in (intake.get("seen") or {}).values():
        if not isinstance(v, dict) or v.get("client") != t["client_slug"] or v.get("outcome") != "filed":
            continue
        if str(v.get("kind") or "") not in t["kinds"]:
            continue
        when = pr_when(v.get("received"))
        if when and start < when <= end:
            hits.append(when)
    return min(hits) if hits else None


def _ticked(item_id):
    if not item_id:
        return False
    try:
        row = api.workq.get(todo_id=item_id)
    except Exception:
        return False
    return bool(row) and str(row.get("status") or "") in ("done", "completed")


for t in timers:
    tz = ZoneInfo(t["tz"])
    today = now.astimezone(tz).date()
    for back in range(TIMER_LOOKBACK_DAYS + 1):
        d = today - datetime.timedelta(days=back)
        if not tm_falls_on(t, d):
            continue
        key = t["key"] + "|" + d.isoformat()
        occ = occurrences.get(key) or {}
        if occ.get("closed") or (back and not occ):
            # Earlier days only carry on what was started on the day.
            continue
        due = tm_at(d, t["due"], tz)
        remind = tm_at(d, t["remind"], tz) if t["remind"] else None
        cutoff = tm_at(d, t["cutoff"], tz) if t["cutoff"] else None
        start = remind or due
        if t["done_when"] == "email":
            # Anything since the previous due time counts, including a late one that rolled to this pay run.
            met = _received(t, due - datetime.timedelta(days=tm_period_days(t)), now)
        else:
            met = now if _ticked(occ.get("item_id")) else None
        done = occ.get("stages") or []
        stages = []
        if met:
            stages.append("met")
        else:
            if now < start:
                continue
            if remind and "remind" not in done and now < due:
                stages.append("remind")
            if t["done_when"] == "workq" and not occ.get("item_id") and not stages:
                stages.append("open")
            if now >= due + datetime.timedelta(minutes=t["follow"]) and "follow" not in done:
                stages.append("follow")
            if t["escalate"] and now >= due + datetime.timedelta(minutes=t["escalate"]) and "escalate" not in done:
                stages.append("escalate")
            if cutoff and now >= cutoff and "cutoff" not in done:
                stages.append("cutoff")
        if not stages:
            continue
        late_by = int((met - due).total_seconds() // 60) if met else 0
        actions.append({
            "key": key, "client": t["client"], "client_slug": t["client_slug"], "timer": t["name"],
            "stages": stages, "done_when": t["done_when"], "contacts": t["contacts"],
            "assignee_email": t["assignee_email"], "tz": t["tz"],
            "due": pr_iso(due), "due_text": tm_clock(due, tz),
            "cutoff": pr_iso(cutoff) if cutoff else "", "cutoff_text": tm_hm(cutoff, tz) if cutoff else "",
            "met_at": pr_iso(met) if met else "", "late_by": max(late_by, 0),
            "after_cutoff": bool(met and cutoff and met > cutoff),
        })
        status.append(t["client"] + " · " + t["name"] + ": " + ", ".join(stages))

problem = "" if timers or problems else "no-timers"

