            follow = tm_minutes(t.get("follow_up_after"), 30)
            escalate = tm_minutes(t.get("escalate_after"), 60)
            if follow == "bad" or escalate == "bad":
                bad.append("\"follow_up_after\" and \"escalate_after\" are minutes after the due time")
            elif escalate and escalate <= follow:
                bad.append("\"escalate_after\" must be later than \"follow_up_after\"")
            done_when = str(t.get("done_when") or "email").strip().lower()
            if done_when not in ("email", "workq"):
                bad.append("\"done_when\" must be email or workq")
            kinds = [str(k).strip().lower() for k in (t.get("kinds") or ["timesheets"]) if str(k or "").strip()]
            contacts = [str(a or "").strip().lower() for a in t.get("contacts") or [] if str(a or "").strip()]
            wrong = [a for a in contacts if not re.match(r"^[\w.+'-]+@[\w-]+(\.[\w-]+)+$", a)]
            if wrong:
                bad.append("not an email address: " + ", ".join(wrong))
            if bad:
                problems.append(where + "; ".join(bad))
                continue
            timers.append({
                "key": slug + "|" + pr_slug(label), "client": name, "client_slug": slug, "name": label,
                "every": every, "day": day, "first": first, "due": due, "remind": remind, "cutoff": cutoff,
                "follow": follow, "escalate": escalate or None, "done_when": done_when, "kinds": kinds,
                "contacts": contacts, "tz": tz_name,
                "assignee_email": str(c.get("assignee_email") or "").strip().lower(),
            })
    return timers, problems


def tm_falls_on(t, d):
    """True when timer t is due on local date d."""
    if t["every"] == "month":
        if t["day"] == "last":
            return (d + datetime.timedelta(days=1)).month != d.month
        return d.day == t["day"]
    if d.weekday() != t["day"]:
        return False
    return t["every"] == "week" or (d - t["first"]).days % 14 == 0


def tm_period_days(t):
    return {"week": 7, "fortnight": 14, "month": 28}[t["every"]]


def tm_at(d, tm, tz):
    return datetime.datetime.combine(d, tm).replace(tzinfo=tz)


def tm_clock(when, tz):
    """"10:30 Mon 02-Nov-26" in the client's time zone."""
    local = when.astimezone(tz)
    return local.strftime("%H:%M") + " " + DAYS[local.weekday()] + " " + pr_day(local)


def tm_hm(when, tz):
    return when.astimezone(tz).strftime("%H:%M")

