settings = pr_read_json(PR_SETTINGS) or {}
state = pr_read_json(PR_TIMERS) or {}
occurrences = state.get("occurrences") or {}
now = datetime.datetime.now(datetime.timezone.utc)
counts = {"reminders": 0, "follow_ups": 0, "escalated": 0, "cut_offs": 0, "received": 0}
lines = []
changed = False
_cache = {}


def _user_id(email):
    email = str(email or "").strip().lower()
    if not email:
        return ""
    if "users" not in _cache:
        try:
            _cache["users"] = api.users.list()
        except Exception:
            _cache["users"] = []
    for u in _cache["users"] or []:
        if str(u.get("email") or "").strip().lower() == email:
            return str(u.get("id") or "")
    return ""


def _open(todo_id):
    try:
        t = api.workq.get(todo_id=todo_id) if todo_id else None
    except Exception:
        return None
    if not t or str(t.get("status") or "") in ("done", "cancelled", "completed", "archived"):
        return None
    return t


def _draft(a, kind):
    """Saves the reminder or follow-up in the owner's Outlook Drafts for a person to check and send. Never sends.
    Returns (link, error)."""
    if not a["contacts"]:
        return "", "no contacts set for this timer"
    what = a["timer"].lower()
    if kind == "remind":
        subject = "Reminder: " + a["timer"] + " due by " + a["due_text"]
        body = ("Hi,\n\nA quick reminder that " + what + " for this pay run are due by " + a["due_text"] + "."
                + (" Anything received after " + a["cutoff_text"] + " will go into the next pay run." if a["cutoff_text"] else "")
                + "\n\nThanks")
    else:
        subject = "Follow-up: " + a["timer"] + " were due " + a["due_text"]
        body = ("Hi,\n\nWe haven't received " + what + " yet. They were due by " + a["due_text"]
                + ". Could you send them through as soon as you can so the pay run isn't held up?"
                + (" Anything received after " + a["cutoff_text"] + " will go into the next pay run." if a["cutoff_text"] else "")
                + "\n\nThanks")
    try:
        res = api.connectors.invoke(server=SEND_SERVER, tool="create_draft_email",
                                    args={"to": a["contacts"], "subject": subject, "body": body})
    except Exception as exc:
        err = str(exc)[:200]
        return "", ("the Microsoft 365 send connection needs reconnecting (" + err + ")" if pr_auth_error(err) else err)
    if isinstance(res, str):
        try:
            res = json.loads(res)
        except ValueError:
            res = {}
    return str((res or {}).get("webLink") or ""), ""


def _draft_line(link, err, kind):
    word = "reminder" if kind == "remind" else "follow-up"
    if err:
        return "- **Email:** couldn't save a " + word + " draft (" + err + "). Contact them directly."
    if link:
        return "- **Email:** a " + word + " draft is in your Outlook Drafts. Check it and send it: [open the draft](" + link + ")"
    return "- **Email:** a " + word + " draft is in your Outlook Drafts. Check it and send it."


def _title(a):
    return "Payroll cut-off · " + a["client"] + " · " + a["timer"] + " due " + a["due_text"]


def _create(a, occ, first_lines, priority, add_owner=False):
    tz = ZoneInfo(a["tz"])
    done_text = ("a payroll email of this kind arrives from the client (the email intake records it)"
                 if a["done_when"] == "email" else "you mark this item done")
    desc = "\n".join(first_lines + [
        "",
        "- **Client:** " + a["client"],
        "- **Due:** " + a["due_text"] + (" (cut-off " + a["cutoff_text"] + ")" if a["cutoff_text"] else ""),
        "- **Closes when:** " + done_text,
        "- **Opened by:** Payroll cut-off reminders & SLA timers",
    ])
    owner = _user_id(settings.get("owner_email"))
    ids = [x for x in [_user_id(a["assignee_email"]) or owner] + ([owner] if add_owner else []) if x]
    ids = sorted(set(ids), key=ids.index)
    t = api.workq.create(
        title=_title(a)[:200], scope="org", description=desc, priority=priority,
        due_date=str((pr_when(a["due"]) or now).astimezone(tz).date()), assignee_ids=ids or None,
        labels=["payroll", "cut-off"],
    )
    occ["item_id"] = str(t.get("id") or "")


def _say(occ, body):
    if occ.get("item_id"):
        api.workq.comment(todo_id=occ["item_id"], body=body)


for a in params.get("actions") or []:
    occ = occurrences.get(a["key"]) or {"stages": [], "due": a["due"], "client": a["client"], "timer": a["timer"]}
    occurrences[a["key"]] = occ
    tz = ZoneInfo(a["tz"])
    stages = a["stages"]
    try:
        if "met" in stages:
            met = pr_when(a["met_at"])
            on_time = a["late_by"] == 0
            occ.update({"met_at": a["met_at"], "late_by": a["late_by"], "closed": True})
            counts["received"] += 1
            if _open(occ.get("item_id")):
                if a["done_when"] == "email":
                    text = ("Received " + tm_hm(met, tz) + ", " + ("on time." if on_time else str(a["late_by"]) + " min after the due time."))
                else:
                    text = "Marked done " + tm_hm(met, tz) + ("." if on_time else ", " + str(a["late_by"]) + " min after the due time.")
                if a["after_cutoff"]:
                    # PG13: late items roll to the next pay run and are recorded. A person decides, so it stays open.
                    _say(occ, text + " This is after the " + a["cutoff_text"] + " cut-off, so it goes into the next pay "
                         "run unless you decide otherwise. Close this item once that's handled.")
                else:
                    _say(occ, text)
                    api.workq.complete(todo_id=occ["item_id"])
        if "remind" in stages or "open" in stages:
            first = []
            if "remind" in stages:
                link, err = _draft(a, "remind")
                first = ["**What to do:** Send the reminder for " + a["timer"].lower() + ".", "", _draft_line(link, err, "remind")]
                counts["reminders"] += 1
            else:
                first = ["**What to do:** Get " + a["timer"].lower() + " done by " + a["due_text"] + ", then mark this item done."]
            _create(a, occ, first, "medium")
        if "follow" in stages:
            link, err = _draft(a, "follow")
            head = "Nothing received yet: it was due " + a["due_text"] + "."
            if a["done_when"] == "workq":
                head = "Not marked done yet: it was due " + a["due_text"] + "."
            if _open(occ.get("item_id")):
                _say(occ, "**Follow up.** " + head + "\n\n" + _draft_line(link, err, "follow"))
                api.workq.update(todo_id=occ["item_id"], priority="high")
            else:
                _create(a, occ, ["**What to do:** Follow up. " + head, "", _draft_line(link, err, "follow")], "high")
            counts["follow_ups"] += 1
        if "escalate" in stages:
            owner = _user_id(settings.get("owner_email"))
            if not _open(occ.get("item_id")):
                _create(a, occ, ["**What to do:** Escalated: still nothing an hour or more after the due time ("
                                 + a["due_text"] + ")."], "high", add_owner=True)
            else:
                row = api.workq.get(todo_id=occ["item_id"]) or {}
                ids = [str(x) for x in row.get("assigneeIds") or []]
                if owner and owner not in ids:
                    api.workq.update(todo_id=occ["item_id"], assignee_ids=ids + [owner])
                _say(occ, "**Escalated.** Still nothing at " + tm_hm(now, tz) + " (due " + tm_hm(pr_when(a["due"]), tz)
                     + ")." + (" Added the payroll owner." if owner and owner not in ids else ""))
            counts["escalated"] += 1
        if "cutoff" in stages:
            if not _open(occ.get("item_id")):
                _create(a, occ, ["**What to do:** The " + a["cutoff_text"] + " cut-off has passed with nothing received."], "high")
            _say(occ, "**Cut-off passed** (" + a["cutoff_text"] + "). Anything that arrives from now on goes into the next "
                 "pay run, and will be noted here.")
            counts["cut_offs"] += 1
    except Exception as exc:
        # Recorded, not retried: the next run doesn't repeat a stage that's already marked.
        lines.append(a["client"] + " · " + a["timer"] + ": " + str(exc)[:200])
    occ["stages"] = sorted(set((occ.get("stages") or []) + [s for s in stages if s != "met"]))
    changed = True

problems = [str(p) for p in params.get("problems") or []]
key = hashlib.sha256(json.dumps(problems).encode()).hexdigest()[:16] if problems else ""
if key != (state.get("problems_key") or ""):
    if problems and not _open((state.get("problems_item") or "")):
        owner = _user_id(settings.get("owner_email"))
        t = api.workq.create(
            title="Payroll cut-off timers need fixing", scope="org", priority="medium",
            due_date=str(now.astimezone(pr_tz(settings)).date()), assignee_ids=[owner] if owner else None,
            labels=["payroll", "cut-off", "setup"],
            description="\n".join(["**What to do:** These timers in Knowledge, Payroll/clients.json, are switched off "
                                   "until they're fixed:", ""] + ["- " + p for p in problems]))
        state["problems_item"] = str(t.get("id") or "")
    elif not problems and _open(state.get("problems_item") or ""):
        _say({"item_id": state.get("problems_item")}, "All timers are fine now. This can be closed.")
    elif problems:
        _say({"item_id": state.get("problems_item")}, "Still to fix:\n\n" + "\n".join("- " + p for p in problems))
    state["problems_key"] = key
    changed = True
    lines.append(str(len(problems)) + " timer(s) need fixing.")

if changed:
    cutoff_day = pr_iso(now - datetime.timedelta(days=60))
    state["occurrences"] = {k: v for k, v in occurrences.items() if str(v.get("due") or "") >= cutoff_day}
    state["last_change"] = pr_iso(now)
    api.files.put(file=PR_TIMERS, content=json.dumps(state, indent=2, sort_keys=True))

if params.get("problem") == "no-timers":
    lines.append("No timers set up in Payroll/clients.json yet.")
summary = (str(counts["reminders"]) + " reminder(s), " + str(counts["follow_ups"]) + " follow-up(s), "
           + str(counts["escalated"]) + " escalated, " + str(counts["cut_offs"]) + " cut-off(s), "
           + str(counts["received"]) + " received") + ("" if not lines else ". " + " ".join(lines))
